def Id(n):
    return [[int(i == j) for i in range(n)] for j in range(n)]

def matexp(A, n):
    if n == 0:
        return Id(len(A))
    h = matexp(A, n//2)

    R = matmul(h, h)
    if n % 2 == 1:
        R = matmul(A, R)
